import{_ as e,o as t,c as r,a2 as n}from"./chunks/framework.A5mep7Fe.js";const c=JSON.parse('{"title":"📚 02 · RAG 检索增强生成（Retrieval-Augmented Generation）","description":"","frontmatter":{},"headers":[],"relativePath":"03-算法岗-AI-Agent/02-RAG检索增强.md","filePath":"03-算法岗-AI-Agent/02-RAG检索增强.md","lastUpdated":1786806808000}'),o={name:"03-算法岗-AI-Agent/02-RAG检索增强.md"};function l(i,a,s,d,h,g){return t(),r("div",null,[...a[0]||(a[0]=[n(`<h1 id="📚-02-·-rag-检索增强生成-retrieval-augmented-generation" tabindex="-1">📚 02 · RAG 检索增强生成（Retrieval-Augmented Generation） <a class="header-anchor" href="#📚-02-·-rag-检索增强生成-retrieval-augmented-generation" aria-label="Permalink to &quot;📚 02 · RAG 检索增强生成（Retrieval-Augmented Generation）&quot;">​</a></h1><blockquote><p>当前<strong>落地最广</strong>的 Agent 能力。解决大模型「知识过时、易幻觉、不可溯源」三大痛点。面试几乎必问。</p></blockquote><hr><h2 id="一、为什么需要-rag" tabindex="-1">一、为什么需要 RAG？ <a class="header-anchor" href="#一、为什么需要-rag" aria-label="Permalink to &quot;一、为什么需要 RAG？&quot;">​</a></h2><p>LLM 的局限：训练数据有截止日期、私有知识不知、易编造。RAG = <strong>生成前先「查资料」</strong>，把相关资料塞进上下文。</p><blockquote><p>本质：用「检索」补足 LLM 的「参数化记忆」短板，让回答<strong>可溯源、可更新、可控</strong>。</p></blockquote><hr><h2 id="二、rag-标准流水线" tabindex="-1">二、RAG 标准流水线 <a class="header-anchor" href="#二、rag-标准流水线" aria-label="Permalink to &quot;二、RAG 标准流水线&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>文档 → 切片(Chunk) → 嵌入(Embedding) → 存入向量库</span></span>
<span class="line"><span>                                      ↓</span></span>
<span class="line"><span>用户问题 → 嵌入 → 检索(Top-k) → 重排(Rerank) → 拼接上下文 → LLM 生成</span></span></code></pre></div><h3 id="_1-文档切片-chunking" tabindex="-1">1. 文档切片（Chunking） <a class="header-anchor" href="#_1-文档切片-chunking" aria-label="Permalink to &quot;1. 文档切片（Chunking）&quot;">​</a></h3><ul><li>固定长度 vs 语义切分（按标题/段落/句子边界）</li><li>重叠（overlap）避免切断语义</li><li>元数据保留（来源、时间、章节）便于过滤</li></ul><h3 id="_2-嵌入-embedding" tabindex="-1">2. 嵌入（Embedding） <a class="header-anchor" href="#_2-嵌入-embedding" aria-label="Permalink to &quot;2. 嵌入（Embedding）&quot;">​</a></h3><ul><li>把文本映射为向量，语义相近则向量相近</li><li>选模型：BGE、E5、OpenAI text-embedding 等（中文注意选中文强模型）</li></ul><h3 id="_3-检索-retrieval" tabindex="-1">3. 检索（Retrieval） <a class="header-anchor" href="#_3-检索-retrieval" aria-label="Permalink to &quot;3. 检索（Retrieval）&quot;">​</a></h3><ul><li><strong>稠密检索</strong>（向量相似度，ANN 索引：HNSW/IVF）</li><li><strong>稀疏检索</strong>（BM25，关键词精确）</li><li><strong>混合检索</strong>（Hybrid = 稠密 + 稀疏，RRF 融合）← 效果最好</li></ul><h3 id="_4-重排-rerank" tabindex="-1">4. 重排（Rerank） <a class="header-anchor" href="#_4-重排-rerank" aria-label="Permalink to &quot;4. 重排（Rerank）&quot;">​</a></h3><ul><li>初检 Top-k（如 20）→ 精排模型（Cross-Encoder）重排 → 取 Top-n（如 5）</li><li>显著提升相关性</li></ul><h3 id="_5-生成" tabindex="-1">5. 生成 <a class="header-anchor" href="#_5-生成" aria-label="Permalink to &quot;5. 生成&quot;">​</a></h3><ul><li>把「问题 + 检索片段」拼成 prompt，要求模型<strong>只基于片段回答并标注来源</strong></li></ul><hr><h2 id="三、进阶-rag-面试加分" tabindex="-1">三、进阶 RAG（面试加分） <a class="header-anchor" href="#三、进阶-rag-面试加分" aria-label="Permalink to &quot;三、进阶 RAG（面试加分）&quot;">​</a></h2><ul><li><strong>Query 改写/扩展</strong>：把口语问题改写为规范检索词；多query 分解复杂问题</li><li><strong>Self-RAG</strong>：模型自判「是否需要检索」「检索片段是否相关」</li><li><strong>GraphRAG</strong>：用知识图谱做全局摘要/社区检索，适合「总结整个文档库」类问题</li><li><strong>RAPTOR</strong>：递归摘要建树，兼顾细节与全局</li><li><strong>元数据过滤</strong>：先按时间/来源过滤再检索</li><li><strong>重排 + 上下文压缩</strong>：去掉无关句，省 token</li></ul><hr><h2 id="四、评估-如何知道-rag-好不好" tabindex="-1">四、评估（如何知道 RAG 好不好） <a class="header-anchor" href="#四、评估-如何知道-rag-好不好" aria-label="Permalink to &quot;四、评估（如何知道 RAG 好不好）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>指标/方法</th></tr></thead><tbody><tr><td>检索质量</td><td>Recall@k、MRR、NDCG</td></tr><tr><td>生成质量</td><td>Faithfulness（不幻觉）、Answer Relevancy、Context Precision/Recall（RAGAS）</td></tr><tr><td>端到端</td><td>人工评估、LLM-as-Judge、线上 AB</td></tr></tbody></table><hr><h2 id="五、高频追问" tabindex="-1">五、高频追问 <a class="header-anchor" href="#五、高频追问" aria-label="Permalink to &quot;五、高频追问&quot;">​</a></h2><p><strong>Q1：RAG 和微调怎么选？</strong></p><blockquote><p>需「接入私有/时效知识 + 可溯源」→ RAG；需「改变模型行为/风格/能力」→ 微调。常结合：微调定能力，RAG 供知识。</p></blockquote><p><strong>Q2：检索不准怎么优化？</strong></p><blockquote><p>切片策略、换/微调 embedding、加 BM25 混合、加重排、query 改写、元数据过滤。先定位是「召回不足」还是「排序不对」。</p></blockquote><p><strong>Q3：为什么需要重排（Rerank）？</strong></p><blockquote><p>初检用 ANN 快但粗糙；rerank 用更贵但准的 Cross-Encoder 精排，用少量候选换质量大幅提升，性价比高。</p></blockquote><p><strong>Q4：RAG 幻觉怎么治？</strong></p><blockquote><p>要求「仅基于上下文」+ 片段引用 + 无检索则拒答 + Faithfulness 评测 + 关键事实抽取校验。</p></blockquote><hr><p>➡️ 下一步：<a href="./03-记忆系统与工具调用">03-记忆系统与工具调用</a></p>`,37)])])}const p=e(o,[["render",l]]);export{c as __pageData,p as default};
